import sys

q = int(input())
in_stack, out_stack = [], []      # new items go in; the front is on top of out_stack
out = []

def front_stack():
    if not out_stack:                 # refill only when empty: each item moves at most once
        while in_stack:
            out_stack.append(in_stack.pop())
    return out_stack

for _ in range(q):
    op = input().split()
    if op[0] == "push":
        in_stack.append(op[1])
    elif op[0] == "pop":
        out.append(front_stack().pop())
    else:
        out.append(front_stack()[-1])
sys.stdout.write("\n".join(out) + "\n")

