using namespace std;
int main() {
    int R, C;
    cin >> R >> C;
    vector<vector<int>> g(R, vector<int>(C));
    queue<array<int, 3>> q;  // row, column, minute
    int fresh = 0;
    for (int r = 0; r < R; r++)
        for (int c = 0; c < C; c++) {
            cin >> g[r][c];
            if (g[r][c] == 2) q.push({r, c, 0});
            else if (g[r][c] == 1) fresh++;
        }
    int minutes = 0, dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
    while (!q.empty()) {
        auto [r, c, t] = q.front();
        q.pop();
        minutes = max(minutes, t);
        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d], nc = c + dc[d];
            if (nr >= 0 && nr < R && nc >= 0 && nc < C && g[nr][nc] == 1) {
                g[nr][nc] = 2;
                fresh--;
                q.push({nr, nc, t + 1});
            }
        }
    }
    cout << (fresh == 0 ? minutes : -1) << "\n";
    return 0;
}

